final class realm_value extends ffi.Struct {
  external UnnamedUnion values;

  @ffi.UnsignedInt()
  external int typeAsInt;

  realm_value_type get type => realm_value_type.fromValue(typeAsInt);
  set type(realm_value_type value) => typeAsInt = value.value;
}

typedef realm_value_t = realm_value;

/// Value types
enum realm_value_type {
  RLM_TYPE_NULL(0),
  RLM_TYPE_INT(1),
  RLM_TYPE_BOOL(2),
  RLM_TYPE_STRING(3),
  RLM_TYPE_BINARY(4),
  RLM_TYPE_TIMESTAMP(5),
  RLM_TYPE_FLOAT(6),
  RLM_TYPE_DOUBLE(7),
  RLM_TYPE_DECIMAL128(8),
  RLM_TYPE_OBJECT_ID(9),
  RLM_TYPE_LINK(10),
  RLM_TYPE_UUID(11),
  RLM_TYPE_LIST(12),
  RLM_TYPE_DICTIONARY(13);

  final int value;
  const realm_value_type(this.value);

  static realm_value_type fromValue(int value) => switch (value) {
    0 => RLM_TYPE_NULL,
    1 => RLM_TYPE_INT,
    2 => RLM_TYPE_BOOL,
    3 => RLM_TYPE_STRING,
    4 => RLM_TYPE_BINARY,
    5 => RLM_TYPE_TIMESTAMP,
    6 => RLM_TYPE_FLOAT,
    7 => RLM_TYPE_DOUBLE,
    8 => RLM_TYPE_DECIMAL128,
    9 => RLM_TYPE_OBJECT_ID,
    10 => RLM_TYPE_LINK,
    11 => RLM_TYPE_UUID,
    12 => RLM_TYPE_LIST,
    13 => RLM_TYPE_DICTIONARY,
    _ => throw ArgumentError('Unknown value for realm_value_type: $value'),
  };
}

